using System;using System.Diagnostics;using TGLL;
class FarmLevelRangeTests {
 static void C(bool b,string m){if(!b)throw new Exception(m);}static FarmSpot Spot(int map,int level,int mob=-2){return new FarmSpot{MapId=map,MapName="ordinary",MobId=mob,MobName="monster",Level=level,X=0,Y=0};}
 static int Main(){try{
 var at52=Spot(74,52);var at56=Spot(88,56);var choices=new[]{Spot(79,50),at52,at56,Spot(81,48)};
 C(NativeBackend.SelectFarmSpot(choices,52,true)==at52,"exact map level preferred");C(NativeBackend.SelectFarmSpot(choices,55,true)==at56,"level-up selects next suitable map");C(NativeBackend.SelectFarmSpot(new[]{Spot(74,55)},52,true)!=null,"upper +3 included");C(NativeBackend.SelectFarmSpot(new[]{Spot(74,49)},52,true)!=null,"lower -3 included");C(NativeBackend.SelectFarmSpot(new[]{Spot(74,56),Spot(81,48)},52,true)==null,"outside ±3 excluded");C(NativeBackend.SelectFarmSpot(new[]{Spot(69,52),Spot(18,52)},52,true)==null,"village and dungeon excluded");C(NativeBackend.SelectFarmSpot(choices,0,true)==null,"unknown character level waits");C(NativeBackend.SelectFarmSpot(new[]{Spot(74,52),Spot(79,52)},52,true,79).MapId==79,"equal targets retain current map");C(NativeBackend.SelectFarmSpot(new[]{Spot(74,90)},52,false)!=null,"manual nearest mode remains unrestricted");
 C(NativeBackend.ResolveAutoFarmSpot(at52,null,new FarmSpot[0],59,52,100,100)==at52,"cross-map placeholder routes only to map");C(NativeBackend.ResolveAutoFarmSpot(at52,null,new FarmSpot[0],74,52,100,100)==null,"never enable combat at placeholder without observed monster");var near=Spot(74,53,123);near.X=400;near.Y=300;at52.Zone=7;var actual=NativeBackend.ResolveAutoFarmSpot(at52,null,new[]{Spot(74,56,5),near},74,52,100,100);C(actual!=null&&actual.MobId==123&&actual.X==400&&actual.Y==300&&actual.Zone==7,"resolve actual in-range mob coordinate and fixed zone");C(Object.ReferenceEquals(NativeBackend.ResolveAutoFarmSpot(at52,actual,new FarmSpot[0],74,52,100,100),actual),"retain verified position between respawns");C(NativeBackend.ResolveAutoFarmSpot(at52,actual,new FarmSpot[0],74,57,100,100)==null,"old mob outside new level range no longer accepted");
 using(var r=new Remote(Process.GetCurrentProcess())){long d=r.Allocate(4096);var job=new NativeJob("fixture","range","",null,true){FarmEnabled=true,FarmArrived=true,FarmRouteSent=true,GameAutoWanted=true,UpRequested=true};NativeBackend.HoldFarmForLevel(r,d,job,"waiting range");C(job.FarmEnabled&&job.UpRequested&&!job.FarmArrived&&!NativeBackend.GameAutoDesired(job)&&BitConverter.ToInt32(r.Read(d,4),0)==6,"no match pauses combat and route without clearing persistent Up");}
 Console.WriteLine("PASS: inclusive ±3, closest/current-map ties, level-up retarget, no village/instance fallback, actual mob coordinates before combat, fixed zones, respawn stability and waiting without clearing Up.");return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
